export const newSegmentModelMatches = (record, definition) => {
    const type = String(record.segment_type || '').toLowerCase().replace(/[-_]/g, ' ');
    const name = String(record.name || '').toLowerCase();
    const accepted = [definition.key, definition.label, ...(definition.aliases || [])].map((value) => value.toLowerCase().replace(/[-_]/g, ' '));
    return accepted.some((value) => type === value || type.includes(value) || name.includes(value));
};
